hooks.command:
f=$(python3 -c "
import json, sys
try:
    d = json.load(sys.stdin)
except Exception:
    d = {}
print((d.get('tool_response') or {}).get('filePath') or (d.get('tool_input') or {}).get('file_path') or '')
")
case "$f" in
  *.py) uv run ruff check --fix "$f" >/dev/null 2>&1; uv run ruff format "$f" >/dev/null 2>&1 ;;
esac
true

python3 -c "
import json, sys
from pathlib import Path

try:
    d = json.load(sys.stdin)
except Exception:
    sys.exit(0)

path = (d.get('tool_input') or {}).get('file_path')
if not path:
    sys.exit(0)

p = Path(path)
reason = None

if p.name == '.env':
    reason = '.env holds live secrets -- edit it directly, not through Claude Code.'
elif p.name == 'uv.lock':
    reason = 'uv.lock is generated -- run \`uv lock\` or \`uv sync\`, do not hand-edit it.'
else:
    parts = p.parts
    is_migration = any(
        parts[i] == 'migrations' and parts[i + 1] == 'versions'
        for i in range(len(parts) - 1)
    ) and p.suffix == '.py'
    if is_migration:
        reason = 'migrations/versions/ is applied history -- use \`alembic revision\`, do not hand-edit an existing migration.'

if reason:
    print(f'Blocked: {path}', file=sys.stderr)
    print(reason, file=sys.stderr)
    sys.exit(2)
sys.exit(0)
"
